        "help_example_hierarchy_description" to MessageForms(other = "Une instance de l’inverseur donne Y=1 pour A=0 et Y=0 pour A=1."),
        "help_example_hierarchy_instructions" to MessageForms(other = "Basculez A dans le circuit principal, puis ouvrez l’instance de l’inverseur dans l’arborescence des circuits."),
        "help_example_hierarchy_title" to MessageForms(other = "Sous-circuit inverseur"),
