        "help_examples_intro" to MessageForms(other = "Bir örneği düzenlemek için çalışma alanında ayrı bir kopya açın. Referans senaryosu ayrı bir simülasyonda sınanır ve açık projeniz değişmez."),
        "help_guide_connections_step_1" to MessageForms(other = "Kablo aracını seçin. Başlamak için bir terminale veya ızgara noktasına, ardından hedefe dokunun. Bekleyen kabloyu iptal etmek için başlangıca yeniden dokunun veya Escape tuşuna basın."),
        "help_guide_connections_step_2" to MessageForms(other = "Kabloların kesişmesi her zaman birleşim noktası oluşturmaz. Uç bağlantılarını ve bit genişliklerini kontrol edin. Tek tek bitleri eşlemek için Ayırıcı / Birleştirici (Splitter), uzaktaki noktaları bağlamak için aynı adlı tüneller kullanın."),
        "help_guide_connections_step_3" to MessageForms(other = "Erişilebilir Devre Gezgini bileşenleri, terminalleri ve kabloları listeler. Çizim alanında hassas dokunuşlara gerek kalmadan öğeleri seçebilir, bağlayabilir ve kaldırabilirsiniz."),
        "help_guide_connections_title" to MessageForms(other = "Kabloları Bağla ve İncele"),
        "help_guide_diagnostics_step_1" to MessageForms(other = "Simülasyonu duraklatın ve Tanılama'yı açın. Uyumsuz bit genişliklerini, çakışan sürücüleri, desteklenmeyen bileşenleri ve kararlı duruma ulaşmayan geri beslemeyi bulmak için raporu filtreleyin."),
        "help_guide_diagnostics_step_2" to MessageForms(other = "İlgili devre ve bileşene gitmek için bir tanılama sonucu seçin. Örnek yolları, aynı alt devrenin ayrı kopyalarını birbirinden ayırır."),
        "help_guide_diagnostics_step_3" to MessageForms(other = "İstatistikler görünümü devre içeriğini ve hiyerarşi açıldığında ortaya çıkan örnekleri sayar. Hata içermeyen bir rapor, programın veya devrenin istenen mantığı uyguladığını kanıtlamaz."),
        "help_guide_diagnostics_title" to MessageForms(other = "Devre Sorunlarını Bul"),
        "help_guide_editing_step_1" to MessageForms(other = "Kütüphaneden bir bileşen seçin ve eklemek için ızgaraya dokunun. Bileşen veya grup seçmek için Seç aracını, seçimi sürüklemek için Taşı aracını kullanın."),
        "help_guide_editing_step_2" to MessageForms(other = "Etiketi ve tanımlı öznitelikleri düzenlemek için Özellikler'i açın. Geçersiz değerler devreyi değiştirmez. Genişlik veya yön değiştiğinde terminalleri denetleyin."),
        "help_guide_editing_step_3" to MessageForms(other = "Geri Al ve Yeniden Yap, devre düzenlemelerine uygulanır. Kopyala, Kes, Yapıştır, Çoğalt ve Sil, geçerli seçim üzerinde çalışır. Klavyede Ctrl veya Command tuşunu C, X, V, D ve Z ile kullanın."),
        "help_guide_editing_title" to MessageForms(other = "Bileşenleri Düzenle"),
        "help_guide_navigation_step_1" to MessageForms(other = "Devre ağacı tanımları ve örnekleri listeler. Bağımsız simülasyon durumunu incelemek için bir örneği açın. Projenin girişine dönmek için ana devreyi seçin."),
        "help_guide_navigation_step_2" to MessageForms(other = "Sığdır, devreyi ekrana sığdırır. Seçimi Sığdır, seçili bileşenleri ve kabloları ekrana sığdırır. Yakınlaştırmak, uzaklaştırmak ve görünümü kaydırmak için iki parmak kullanın. Yakınlaştırma sırasında hareketinizin altındaki nokta sabit kalır."),
        "help_guide_navigation_step_3" to MessageForms(other = "Arama, devre adlarını, bileşen etiketlerini, kütüphane bileşenlerini ve komutları bulur. Dar ekranda diğer araçları görmek için araç sekmelerini yatay kaydırın."),
        "help_guide_navigation_title" to MessageForms(other = "Projede Gezin"),
        "help_guide_saving_step_1" to MessageForms(other = "Çalışma alanı projelerin yerel kopyalarını saklar. Bir projeye dönmek için çalışma alanındaki kaydını seçin. Otomatik kaydetme, harici dosyanın üzerine kendiliğinden yazmaz."),
        "help_guide_saving_step_2" to MessageForms(other = "Kopya içe aktarmak veya .circ projesini dışa aktarmak için Dosya menüsünü kullanın. Android sistem belge seçicisini, iPhone ve iPad ise Dosyalar uygulamasını kullanır. İptal ederseniz açık proje değişmez."),
        "help_guide_saving_step_3" to MessageForms(other = "Dosyaya Kaydet yalnızca desteklenen bir harici düzenleme oturumunda etkindir. Sağlayıcı çakışma bildirirse iki sürümü de saklayın veya yeni bir kopya dışa aktarın. Android sağlayıcılarında, dosyanın üzerine güvenli olmayan biçimde yazmamak için Farklı Kaydet kullanılır."),
        "help_guide_saving_step_4" to MessageForms(other = "Paylaş, sistemin paylaşım menüsünden dışa aktarılan bir kopyayı gönderir. Kurtarma bildirimi veya depolama hatası görünürse önemli dosyaları değiştirmeden önce kurtarılan kopyayı inceleyip dışa aktarın."),
        "help_guide_saving_title" to MessageForms(other = "Kaydet, Paylaş ve Kurtar"),
        "help_guide_simulation_step_1" to MessageForms(other = "Giriş pinlerinin değerlerini değiştirmek için Simüle Et aracını seçin. Alt devre örneğindeki pini üst devre sürer. Değerleri incelemek için Sinyaller'i kullanın. Bilinmeyen bitler ve hata bitleri sıfır sayılmaz."),
        "help_guide_simulation_step_2" to MessageForms(other = "Çalıştır, saat sinyallerini sürekli ilerletir. Duraklat, otomatik yürütmeyi durdurur. İlerle, saati bir adım ilerletir. Olay, bekleyen bir yayılım olayını yürütür."),
        "help_guide_simulation_step_3" to MessageForms(other = "Simülasyon seçenekleri frekansı, yayılım sınırını, başlangıçtaki bellek durumunu ve bağlı olmayan kapı girişlerinin davranışını belirler. Saat bileşeninin özellikleri yüksek ve düşük seviyede kalma sürelerini ve fazı belirler."),
        "help_guide_simulation_step_4" to MessageForms(other = "Sıfırla, simülasyon durumunu başa alır. İçe aktarılan SAP-1'i çalıştırmadan önce Reset girişini 0'dan 1'e, ardından yeniden 0'a getirin. Program 56 saat adımı sonra ekranda 08 değerini gösterir."),
